#!/usr/bin/env bash
# SPDX-License-Identifier: MIT
# Atlas KubeKit | By Atlas Richie
# BEGIN ATLAS KUBEKIT VERSION (generated by scripts/update-version.py)
ATLAS_KUBEKIT_VERSION='0.4.0'
if [ "${1:-}" = --version ] || [ "${1:-}" = -V ]; then
  printf 'Atlas KubeKit %s\n' "$ATLAS_KUBEKIT_VERSION"
  exit 0
fi
# END ATLAS KUBEKIT VERSION
# Configure control-plane telemetry endpoints on the node's private address.
set -euo pipefail

NODE_IP="${1:-}"
[ "$(id -u)" -eq 0 ] || { printf '[ERROR] Run as root\n' >&2; exit 1; }
[ -n "$NODE_IP" ] || { printf '[ERROR] Usage: %s <node-ip>\n' "$0" >&2; exit 2; }

python3 - "$NODE_IP" <<'PY'
import ipaddress
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile

try:
    node_ip = str(ipaddress.IPv4Address(sys.argv[1]))
except ipaddress.AddressValueError:
    raise SystemExit("[ERROR] Invalid IPv4 node address")

address_output = subprocess.run(
    ["ip", "-o", "-4", "addr", "show"], check=True, capture_output=True, text=True
).stdout
if not any(line.split()[3].split("/")[0] == node_ip for line in address_output.splitlines() if len(line.split()) > 3):
    raise SystemExit("[ERROR] Node address is not assigned locally; no manifests changed")

manifest_dir = Path("/etc/kubernetes/manifests")
specs = {
    "kube-controller-manager.yaml": ("--bind-address=", "127.0.0.1", node_ip),
    "kube-scheduler.yaml": ("--bind-address=", "127.0.0.1", node_ip),
}
candidates = {}
for filename, (prefix, expected, replacement) in specs.items():
    path = manifest_dir / filename
    if not path.is_file():
        raise SystemExit(f"[ERROR] Missing {path}; this node is not an initialized control plane")
    source = path.read_text()
    lines = source.splitlines(keepends=True)
    matches = [i for i, line in enumerate(lines) if prefix in line and line.lstrip().startswith("- ")]
    if len(matches) != 1:
        raise SystemExit(f"[ERROR] Expected one {prefix} argument in {path}; no manifests changed")
    index = matches[0]
    line = lines[index]
    current = line.split(prefix, 1)[1].strip()
    if current not in (expected, replacement):
        raise SystemExit(f"[ERROR] Refusing unexpected {prefix} value in {path}: {current}")
    changed = False
    if current == expected:
        lines[index] = line.replace(prefix + expected, prefix + replacement, 1)
        changed = True
    for probe_index, probe_line in enumerate(lines):
        if "host: 127.0.0.1" in probe_line:
            lines[probe_index] = probe_line.replace("host: 127.0.0.1", "host: " + node_ip, 1)
            changed = True
    if changed:
        candidates[path] = "".join(lines)

path = manifest_dir / "etcd.yaml"
if not path.is_file():
    raise SystemExit(f"[ERROR] Missing {path}; this node is not an initialized control plane")
source = path.read_text()
lines = source.splitlines(keepends=True)
matches = [i for i, line in enumerate(lines) if "--listen-metrics-urls=" in line and line.lstrip().startswith("- ")]
if len(matches) != 1:
    raise SystemExit(f"[ERROR] Expected one etcd metrics URL argument in {path}; no manifests changed")
index = matches[0]
line = lines[index]
value = line.split("--listen-metrics-urls=", 1)[1].strip()
urls = [item for item in value.split(",") if item]
local_url = f"http://{node_ip}:2381"
if local_url not in urls:
    if "http://127.0.0.1:2381" not in urls:
        raise SystemExit(f"[ERROR] Refusing unexpected etcd metrics URL in {path}: {value}")
    urls.append(local_url)
    lines[index] = line.replace(value, ",".join(urls), 1)
    candidates[path] = "".join(lines)

if not candidates:
    print(f"[PASS] Control-plane telemetry already binds to {node_ip}")
    raise SystemExit(0)

backup_dir = Path("/var/backups/atlas-kubekit/control-plane-metrics")
backup_dir.mkdir(parents=True, exist_ok=True)
prepared = {}
backups = {}
try:
    for target, contents in candidates.items():
        original = target.stat()
        backup = backup_dir / (target.name + ".before-atlas-metrics")
        if not backup.exists():
            shutil.copy2(target, backup)
        descriptor, temporary = tempfile.mkstemp(prefix="." + target.name + ".", dir=target.parent)
        with os.fdopen(descriptor, "w") as stream:
            stream.write(contents)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, original.st_mode & 0o777)
        os.chown(temporary, original.st_uid, original.st_gid)
        prepared[target] = Path(temporary)
        backups[target] = backup
    for target, temporary in prepared.items():
        os.replace(temporary, target)
except Exception:
    for target, backup in backups.items():
        if target in prepared and not prepared[target].exists():
            shutil.copy2(backup, target)
    raise
finally:
    for temporary in prepared.values():
        temporary.unlink(missing_ok=True)

for target in candidates:
    print(f"[INFO] Updated {target}")
print(f"[INFO] etcd, scheduler, and controller-manager metrics bind only to {node_ip}")
PY

control_plane_metrics_ready() {
  local node_name="$1" port
  for port in 2381 10257 10259; do
    if ! ss -H -lnt "sport = :$port" | grep -Fq "$NODE_IP:$port"; then
      readiness_detail="private metrics listener $NODE_IP:$port"
      return 1
    fi
  done
  if ! KUBECONFIG=/etc/kubernetes/admin.conf kubectl --request-timeout=5s get --raw=/readyz >/dev/null 2>&1; then
    readiness_detail='Kubernetes API /readyz'
    return 1
  fi
  if ! KUBECONFIG=/etc/kubernetes/admin.conf kubectl --request-timeout=5s wait \
    --namespace kube-system --for=condition=Ready --timeout=5s \
    "pod/etcd-$node_name" "pod/kube-controller-manager-$node_name" "pod/kube-scheduler-$node_name" >/dev/null 2>&1; then
    readiness_detail='etcd, controller-manager, or scheduler Pod readiness'
    return 1
  fi
}

if command -v kubectl >/dev/null 2>&1 && [ -s /etc/kubernetes/admin.conf ]; then
  node_name="$(hostname -s)"
  deadline=$((SECONDS + 180))
  # Restarting stacked etcd can temporarily make API calls fail rather than wait.
  while ! control_plane_metrics_ready "$node_name"; do
    if [ "$SECONDS" -ge "$deadline" ]; then
      printf '[ERROR] Timed out waiting for %s after manifest updates\n' "$readiness_detail" >&2
      exit 1
    fi
    sleep 2
  done
  printf '[PASS] Control-plane components are Ready and telemetry listeners are active on %s\n' "$NODE_IP"
fi
